#!/usr/bin/env python3
"""Offline stock ProForge reset. Stop Klipper before applying. Python 3 stdlib only."""
import argparse, base64, datetime, hashlib, json, os, pathlib, re, shutil, subprocess, sys, tempfile, zlib
STOCK_COMMIT = 'd349b1a4c0645e62c620552e2f37b31e9fdfbab9'
STOCK_URL = 'https://github.com/Makertech3D/ProForge-5'
PAYLOAD = ''

def sections(s):
    matches = list(re.finditer(r'^\[([^\]\n]+)\][ \t]*(?:[#;].*)?$', s, re.M))
    return {m[1]: s[m.start(): matches[i+1].start() if i+1<len(matches) else len(s)] for i,m in enumerate(matches)}

def replace_section(s, name, new):
    old = sections(s).get(name)
    if old is None: return s.rstrip()+'\n\n'+new.rstrip()+'\n'
    return s.replace(old,new.rstrip()+'\n\n',1)

def opts(section):
    return dict(re.findall(r'^([A-Za-z_][\w]*)\s*[:=]\s*([^\n]*)',section,re.M))

def setopt(s, section, key, value):
    block = sections(s)[section]
    pat = r'^'+re.escape(key)+r'\s*[:=].*$'
    if re.search(pat,block,re.M): new=re.sub(pat,lambda m:key+': '+value,block,flags=re.M)
    else: new=block.rstrip()+'\n'+key+': '+value+'\n'
    return replace_section(s,section,new)

def stopped():
    result=subprocess.run(['systemctl','is-active','klipper'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True)
    if result.stdout.strip() not in ('inactive','failed'):
        raise ValueError('Stop Klipper first: sudo systemctl stop klipper (finish/cancel any print first).')

def write(path,data):
    fd,tmp=tempfile.mkstemp(prefix='.pf-reset-',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
        os.chmod(tmp,0o644); os.replace(tmp,str(path))
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--config',default='~/printer_data/config')
    ap.add_argument('--dry-run',action='store_true')
    ap.add_argument('--restore',help='Backup folder printed by a previous run; restores only files changed by this script')
    a=ap.parse_args(); root=pathlib.Path(a.config).expanduser().resolve()
    if a.restore:
        stopped(); backup=pathlib.Path(a.restore).expanduser().resolve()
        manifest=json.loads((backup/'manifest.json').read_text())
        if str(root)!=manifest['config']: raise ValueError('Backup belongs to a different config directory.')
        # Back up the stock test files before undoing the reset.
        undo=backup/('before-restore-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
        undo.mkdir()
        for name,info in manifest['originals'].items():
            dest=root/name
            if dest.exists(): shutil.copy2(str(dest),str(undo/name))
            if info['kind']=='missing':
                if dest.exists() or dest.is_symlink(): dest.unlink()
            elif info['kind']=='symlink':
                if dest.exists() or dest.is_symlink(): dest.unlink()
                dest.symlink_to(info['target'])
            else: write(dest,(backup/'originals'/name).read_bytes())
        print('Restored pre-reset files. variables.cfg was not changed. Start Klipper when ready.'); return
    stock=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode())
    current={n:(root/n).read_text() for n in stock if (root/n).exists()}
    for name in ('printer.cfg','macros.cfg','eddy.cfg'):
        if name not in current: raise ValueError('Missing required file: '+name)
    variables=root/'variables.cfg'
    varbytes=variables.read_bytes()
    printer=current['printer.cfg']
    marker=re.search(r'^#\*# .*SAVE_CONFIG.*$',printer,re.M)
    saved=printer[marker.start():] if marker else ''
    active=printer[:marker.start()] if marker else printer
    # Preserve the user's entire bottom section, starting with Case_Light,
    # plus the exact generated calibration block. Refuse unexpected executable tail.
    tailmatch=re.search(r'^\[neopixel Case_Light\]',active,re.M)
    if not tailmatch: raise ValueError('Cannot locate bottom [neopixel Case_Light] section; no files changed.')
    tail=active[tailmatch.start():]
    if any(n.startswith(('gcode_macro','delayed_gcode','include')) for n in sections(tail)):
        raise ValueError('Bottom of printer.cfg contains executable macros/includes; review needed before preserving it.')
    stock['printer.cfg']=stock['printer.cfg'].split('[neopixel Case_Light]',1)[0]+tail.rstrip()+'\n\n'+saved
    # Keep the installed toolboard/enclosure enablement, not recovery includes.
    for name in ['so3_%d.cfg'%i for i in range(5)]+['enclosure.cfg']:
        enabled=bool(re.search(r'^\[include '+re.escape(name)+r'\]',active,re.M))
        stock['printer.cfg']=re.sub(r'^#?\[include '+re.escape(name)+r'\]',('' if enabled else '#')+'[include '+name+']',stock['printer.cfg'],flags=re.M)
    # MCU connections are kept by section name in their corresponding files.
    connections=[]
    for name,text in list(stock.items()):
        for section in sections(text):
            if section=='mcu' or section.startswith('mcu '):
                live=sections(current.get(name,'' )).get(section)
                if not live: raise ValueError('Cannot preserve '+section+' in '+name)
                old=opts(live)
                if not any(k in old for k in ('serial','canbus_uuid')): raise ValueError('Missing MCU connection: '+section)
                block=sections(stock[name])[section]
                block=re.sub(r'^(serial|canbus_uuid|canbus_interface|baud|restart_method)\s*[:=].*\n?','',block,flags=re.M)
                for key in ('serial','canbus_uuid','canbus_interface','baud','restart_method'):
                    if key in old: block=block.rstrip()+'\n'+key+': '+old[key]+'\n'
                stock[name]=replace_section(stock[name],section,block); connections.append(section)
    angles={}
    for macro in ('_SERVO_DOCK','_SERVO_SELECT'):
        block=sections(current['macros.cfg']).get('gcode_macro '+macro,'')
        values=re.findall(r'^\s*(?:SET_SERVO\s+SERVO=toolchanger|_PF_SERVO_TIMED)\s+ANGLE=([0-9]+(?:\.[0-9]+)?)\b',block,re.M)
        if len(values)!=1: raise ValueError('Cannot identify one literal servo angle in '+macro)
        angles[macro]=values[0]
        name='gcode_macro '+macro
        stock['macros.cfg']=replace_section(stock['macros.cfg'],name,re.sub(r'ANGLE=[0-9.]+','ANGLE='+values[0],sections(stock['macros.cfg'])[name]))
    probe='probe_eddy_ng btt_eddy'
    eddy=opts(sections(current['eddy.cfg'])[probe]); offsets={}
    for key in ('x_offset','y_offset','z_offset','tap_adjust_z','tap_target_z'):
        if key in eddy:
            stock['eddy.cfg']=setopt(stock['eddy.cfg'],probe,key,eddy[key]); offsets[key]=eddy[key]
    # Keep servo pulse mapping, so preserved angles mean the same physical position.
    stock['printer.cfg']=replace_section(stock['printer.cfg'],'servo toolchanger',sections(active)['servo toolchanger'])
    # Saved calibration values must not conflict with active stock defaults.
    decoded='\n'.join(line[4:] if line.startswith('#*# ') else '' for line in saved.splitlines())
    for section,block in sections(decoded).items():
        for key in opts(block):
            for name,text in list(stock.items()):
                body=text.split('#*# <',1)[0]
                if section in sections(body):
                    old=sections(body)[section]
                    new=re.sub(r'^('+re.escape(key)+r'\s*[:=].*)$',r'# preserved via SAVE_CONFIG: \1',old,flags=re.M)
                    stock[name]=text.replace(old,new,1)
    # Keep the original save-variables location; never replace variables itself.
    stock['printer.cfg']=setopt(stock['printer.cfg'],'save_variables','filename',opts(sections(active)['save_variables'])['filename'])
    encoded={n:t.encode() for n,t in stock.items()}
    print('Official stock commit:',STOCK_COMMIT)
    print('Preserved servo angles:',angles)
    print('Preserved MCU connections:',', '.join(connections))
    print('Preserved Eddy offsets:',offsets)
    print('Preserved bottom Case_Light/custom sections and exact SAVE_CONFIG block; variables.cfg untouched.')
    print('Replace:',', '.join(sorted(encoded)))
    if a.dry_run: print('DRY RUN: no files changed.'); return
    stopped()
    backup=root.parent/'proforge-backups'/datetime.datetime.now().strftime('pre-stock-%Y%m%d-%H%M%S-%f')
    backup.mkdir(parents=True)
    shutil.copytree(str(root),str(backup/'config'),symlinks=True)
    (backup/'originals').mkdir(); (backup/'stock-staged').mkdir()
    originals={}
    for name,data in encoded.items():
        p=root/name
        if p.is_symlink(): originals[name]={'kind':'symlink','target':os.readlink(str(p))}
        elif p.exists(): originals[name]={'kind':'file'}
        else: originals[name]={'kind':'missing'}
        if p.exists():
            original=p.read_bytes(); (backup/'originals'/name).write_bytes(original)
            originals[name]['sha256']=hashlib.sha256(original).hexdigest()
        (backup/'stock-staged'/name).write_bytes(data)
    log=root.parent/'logs'/'klippy.log'
    if log.exists(): shutil.copy2(str(log),str(backup/'klippy.log'))
    shutil.copy2(__file__,str(backup/'reset_proforge_stock.py'))
    (backup/'manifest.json').write_text(json.dumps({'config':str(root),'stock_commit':STOCK_COMMIT,'originals':originals},indent=2))
    # Check live inputs still match what was reviewed before committing.
    for n,t in current.items():
        if (root/n).read_text()!=t: raise ValueError('Config changed during backup: '+n)
    if variables.read_bytes()!=varbytes: raise ValueError('variables.cfg changed during backup.')
    changed=[]
    try:
        for name,data in encoded.items(): write(root/name,data); changed.append(name)
        for name,data in encoded.items():
            if (root/name).read_bytes()!=data: raise ValueError('Write verification failed: '+name)
        if variables.read_bytes()!=varbytes: raise ValueError('variables.cfg changed unexpectedly.')
    except BaseException:
        for name in reversed(changed):
            p=root/name; info=originals[name]
            if info['kind']=='symlink': p.unlink(); p.symlink_to(info['target'])
            elif info['kind']=='file': write(p,(backup/'originals'/name).read_bytes())
            else: p.unlink()
        raise
    print('\nDONE. Full config backup:',backup)
    print('Recovery files remain on disk but stock printer.cfg no longer includes them.')
    print('No restart or printer movement was performed.')
    print('To undo (with Klipper stopped):')
    import shlex
    print('python3 '+shlex.quote(str(backup/'reset_proforge_stock.py'))+' --config '+shlex.quote(str(root))+' --restore '+shlex.quote(str(backup)))

if __name__=='__main__':
    try: main()
    except Exception as e: print('STOP:',e,file=sys.stderr); sys.exit(1)
